using CTXD.Server.Data;
using Npgsql;

namespace CTXD.Server.Services;

public sealed class WorldScheduledEventService(GameDb db,CanonicalContent content,BattleService battle,GamePushHub push,ILogger<WorldScheduledEventService> log):BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {using var timer=new PeriodicTimer(TimeSpan.FromSeconds(30));do{try{await TickAsync(ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){return;}catch(Exception ex){log.LogError(ex,"World scheduled-event tick failed");}}while(await timer.WaitForNextTickAsync(ct));}

    async Task TickAsync(CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await ResolveNationTaskEndsAsync(c,t,ct);await AdvanceNationRoundsAsync(c,t,ct);var tasks=new List<(long id,int force,int type,int serial,DateTimeOffset start)>();await using(var cmd=new NpgsqlCommand("SELECT id,force_id,task_type,CASE WHEN event_serial>0 THEN event_serial ELSE 1 END,starts_at FROM nation_scheduled_tasks WHERE status=0 AND task_type=ANY($1) AND starts_at<=now() AND ends_at>now() FOR UPDATE",c,t)){cmd.Parameters.AddWithValue(new[]{3,7,8});await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))tasks.Add((r.GetInt64(0),r.GetInt16(1),r.GetInt16(2),r.GetInt32(3),r.GetFieldValue<DateTimeOffset>(4)));}var changed=false;foreach(var task in tasks)changed|=task.type switch{3=>await SpawnInvasionAsync(c,t,task,ct),7=>await SpawnSweepAsync(c,t,task,ct),8=>await SpawnBorderAsync(c,t,task,ct),_=>false};changed|=await TickYellowTurbanAsync(c,t,ct);await ResolveBorderAsync(c,t,ct);await t.CommitAsync(ct);await ProcessBorderDuelsAsync(ct);if(changed)await push.BroadcastAsync("world.updated",new{reason="nation.event.spawn"},ct);}

    async Task ProcessBorderDuelsAsync(CancellationToken ct)
    {var jobs=new List<(long battle,int count)>();await using(var c=await db.DataSource.OpenConnectionAsync(ct)){var rows=new List<(long task,int force,DateTimeOffset start,long battle)>();await using(var q=new NpgsqlCommand("SELECT DISTINCT s.id,s.force_id,s.starts_at,b.id FROM nation_scheduled_tasks s JOIN nation_event_npcs n ON n.scheduled_task_id=s.id AND n.defeated=false JOIN battle_units u ON u.event_npc_id=n.id JOIN battles b ON b.id=u.battle_id AND b.status=0 WHERE s.task_type=8 AND s.status=0 AND s.starts_at<=now() AND s.ends_at>now()",c)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add((r.GetInt64(0),r.GetInt16(1),r.GetFieldValue<DateTimeOffset>(2),r.GetInt64(3)));}foreach(var row in rows){int level;await using(var lv=new NpgsqlCommand("SELECT level FROM nation_forces WHERE force_id=$1",c)){lv.Parameters.AddWithValue(row.force);level=Convert.ToInt32(await lv.ExecuteScalarAsync(ct));}var elapsed=(DateTimeOffset.UtcNow-row.start).TotalMinutes;var wave=content.NationBorderWaves.Where(x=>x.KingdomLevel==level&&x.T<=elapsed).OrderByDescending(x=>x.T).FirstOrDefault();if(wave is null)continue;if(wave.Td>0){var bucket=(long)((DateTimeOffset.UtcNow-row.start).TotalSeconds/wave.Td);if(await ClaimDuelTickAsync(c,row.task,row.battle,$"td:{wave.Index}:{bucket}",1,ct))jobs.Add((row.battle,1));}if(wave.Tb>0){var interval=Math.Min(wave.Tb,10);var bucket=(long)((elapsed-wave.T)/interval);if(bucket>=0&&await ClaimDuelTickAsync(c,row.task,row.battle,$"tb:{wave.Index}:{bucket}",50,ct))jobs.Add((row.battle,50));}}}foreach(var job in jobs)await battle.RunQueuedDuelsAsync(job.battle,job.count,ct);}
    static async Task<bool> ClaimDuelTickAsync(NpgsqlConnection c,long task,long battleId,string key,int count,CancellationToken ct){await using var q=new NpgsqlCommand("INSERT INTO nation_border_duel_ticks(scheduled_task_id,tick_key,battle_id,duel_count) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING",c);q.Parameters.AddWithValue(task);q.Parameters.AddWithValue(key);q.Parameters.AddWithValue(battleId);q.Parameters.AddWithValue(count);return await q.ExecuteNonQueryAsync(ct)==1;}

    async Task<bool> SpawnInvasionAsync(NpgsqlConnection c,NpgsqlTransaction t,(long id,int force,int type,int serial,DateTimeOffset start) task,CancellationToken ct)
    {var elapsed=(DateTimeOffset.UtcNow-task.start).TotalMinutes;var waves=content.NationBarbarianWaves.Where(x=>x.T<=elapsed);var minLevel=1;await using(var lv=new NpgsqlCommand("SELECT GREATEST(1,min(level)) FROM nation_forces",c,t)){minLevel=Convert.ToInt32(await lv.ExecuteScalarAsync(ct));}var barbarian=content.Barbarians.Values.OrderBy(x=>Math.Abs(x.Id-minLevel)).First();var cities=task.force switch{1=>waves.SelectMany(x=>Ids(x.Wei)),2=>waves.SelectMany(x=>Ids(x.Shu)),_=>waves.SelectMany(x=>Ids(x.Wu))};var armies=Ids(task.force switch{1=>barbarian.WeiInvadeArmies,2=>barbarian.ShuInvadeArmies,_=>barbarian.WuInvadeArmies}).ToArray();if(armies.Length==0)return false;var changed=false;foreach(var wave in waves)foreach(var city in Ids(task.force switch{1=>wave.Wei,2=>wave.Shu,_=>wave.Wu}))for(var i=0;i<wave.N;i++)changed|=await InsertAsync(c,t,task.id,task.force,3,city,armies[i%armies.Length],$"wave:{wave.Id}:city:{city}:npc:{i}",ct);return changed;}

    async Task<bool> SpawnSweepAsync(NpgsqlConnection c,NpgsqlTransaction t,(long id,int force,int type,int serial,DateTimeOffset start) task,CancellationToken ct)
    {var level=1;await using(var lv=new NpgsqlCommand("SELECT level FROM nation_forces WHERE force_id=$1",c,t)){lv.Parameters.AddWithValue(task.force);level=Convert.ToInt32(await lv.ExecuteScalarAsync(ct));}var wave=content.NationSweepWaves.FirstOrDefault(x=>x.Index==task.serial&&x.KingdomLevel==level);if(wave is null)return false;var cities=Ids(task.force switch{1=>wave.Wei,2=>wave.Shu,_=>wave.Wu}).ToArray();var armies=Ids(task.force switch{1=>wave.WeiArmies,2=>wave.ShuArmies,_=>wave.WuArmies}).ToArray();if(armies.Length==0)return false;var changed=false;foreach(var city in cities)for(var i=0;i<wave.N;i++)changed|=await InsertAsync(c,t,task.id,task.force,7,city,armies[i%armies.Length],$"round:{wave.Index}:city:{city}:npc:{i}",ct);return changed;}

    async Task<bool> SpawnBorderAsync(NpgsqlConnection c,NpgsqlTransaction t,(long id,int force,int type,int serial,DateTimeOffset start) task,CancellationToken ct)
    {var elapsed=(DateTimeOffset.UtcNow-task.start).TotalMinutes;var level=1;await using(var lv=new NpgsqlCommand("SELECT level FROM nation_forces WHERE force_id=$1",c,t)){lv.Parameters.AddWithValue(task.force);level=Convert.ToInt32(await lv.ExecuteScalarAsync(ct));}var barbarian=content.Barbarians.Values.OrderByDescending(x=>x.Id).First();var armies=Ids(task.force switch{1=>barbarian.WeiInvadeArmies,2=>barbarian.ShuInvadeArmies,_=>barbarian.WuInvadeArmies}).ToArray();if(armies.Length==0)return false;var changed=false;foreach(var wave in content.NationBorderWaves.Where(x=>x.KingdomLevel==level&&x.T<=elapsed)){var configured=Ids(task.force switch{1=>wave.Wei,2=>wave.Shu,_=>wave.Wu}).ToArray();var owned=new List<int>();foreach(var city in configured){await using var owner=new NpgsqlCommand("SELECT 1 FROM world_cities WHERE city_id=$1 AND owner_force_id=$2",c,t);owner.Parameters.AddWithValue(city);owner.Parameters.AddWithValue(task.force);if(await owner.ExecuteScalarAsync(ct)is not null)owned.Add(city);}foreach(var city in owned)for(var i=0;i<wave.N;i++)changed|=await InsertAsync(c,t,task.id,task.force,8,city,armies[i%armies.Length],$"wave:{wave.Index}:city:{city}:npc:{i}",ct);}return changed;}

    static async Task ResolveBorderAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken ct)
    {await using var fail=new NpgsqlCommand("UPDATE nation_scheduled_tasks s SET status=3,dependency_code='result:lost' WHERE s.status=0 AND s.task_type=8 AND EXISTS(SELECT 1 FROM nation_event_npcs n JOIN world_cities w ON w.city_id=n.city_id WHERE n.scheduled_task_id=s.id AND w.owner_force_id<>s.force_id)",c,t);await fail.ExecuteNonQueryAsync(ct);await using var win=new NpgsqlCommand("UPDATE nation_scheduled_tasks s SET status=1,dependency_code='result:won' WHERE s.status IN(0,2) AND s.task_type=8 AND s.ends_at<=now() AND EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id) AND NOT EXISTS(SELECT 1 FROM nation_event_npcs n JOIN world_cities w ON w.city_id=n.city_id WHERE n.scheduled_task_id=s.id AND w.owner_force_id<>s.force_id)",c,t);await win.ExecuteNonQueryAsync(ct);}

    async Task<bool> TickYellowTurbanAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken ct)
    {var groups=new List<(string slot,long task,DateTimeOffset end)>();await using(var find=new NpgsqlCommand("SELECT slot_key,min(id),max(ends_at) FROM nation_scheduled_tasks WHERE task_type=9 AND status=0 AND starts_at<=now() AND ends_at>now() GROUP BY slot_key",c,t)){await using var r=await find.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))groups.Add((r.GetString(0),r.GetInt64(1),r.GetFieldValue<DateTimeOffset>(2)));}var changed=false;foreach(var group in groups){int phase;DateTimeOffset phaseStart;await using(var init=new NpgsqlCommand("INSERT INTO world_yellow_turban_states(slot_key,coordinator_task_id) VALUES($1,$2) ON CONFLICT DO NOTHING",c,t)){init.Parameters.AddWithValue(group.slot);init.Parameters.AddWithValue(group.task);changed|=await init.ExecuteNonQueryAsync(ct)==1;}await using(var state=new NpgsqlCommand("SELECT phase,phase_started_at FROM world_yellow_turban_states WHERE slot_key=$1 AND status=0 FOR UPDATE",c,t)){state.Parameters.AddWithValue(group.slot);await using var r=await state.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))continue;phase=r.GetInt16(0);phaseStart=r.GetFieldValue<DateTimeOffset>(1);}var level=1;await using(var lv=new NpgsqlCommand("SELECT GREATEST(1,max(level)) FROM nation_forces",c,t)){level=Convert.ToInt32(await lv.ExecuteScalarAsync(ct));}changed|=await SpawnYellowPhaseAsync(c,t,group.task,level,phase,ct);if(phase==1&&await PhaseClearedAsync(c,t,group.task,1,ct)){await using var next=new NpgsqlCommand("UPDATE world_yellow_turban_states SET phase=2,phase_started_at=now(),updated_at=now() WHERE slot_key=$1 AND phase=1;UPDATE nation_scheduled_tasks SET event_serial=2 WHERE slot_key=$1 AND task_type=9 AND status=0",c,t);next.Parameters.AddWithValue(group.slot);await next.ExecuteNonQueryAsync(ct);phase=2;phaseStart=DateTimeOffset.UtcNow;changed=true;}if(phase==2){var temples=0;await using(var remain=new NpgsqlCommand("SELECT count(*) FROM world_cities WHERE city_id=ANY($1) AND owner_force_id=104",c,t)){remain.Parameters.AddWithValue(new[]{60,132,193});temples=Convert.ToInt32(await remain.ExecuteScalarAsync(ct));}if(temples>0){var interval=temples switch{3=>30,2=>60,_=>90};var bucket=(long)((DateTimeOffset.UtcNow-phaseStart).TotalSeconds/interval);var phantom=content.NationYellowTurbanNpcs.SingleOrDefault(x=>x.KingdomLevel==level&&x.Type==3);if(phantom is not null)changed|=await InsertAsync(c,t,group.task,0,9,105,phantom.ArmyId,$"phase:2:phantom:{bucket}",ct);}int owner;await using(var city=new NpgsqlCommand("SELECT owner_force_id FROM world_cities WHERE city_id=105",c,t)){owner=Convert.ToInt32(await city.ExecuteScalarAsync(ct));}if(owner is >=1 and <=3){await using var finish=new NpgsqlCommand("UPDATE world_yellow_turban_states SET status=1,winner_force_id=$2,updated_at=now() WHERE slot_key=$1;UPDATE nation_scheduled_tasks SET status=CASE WHEN force_id=$2 THEN 1 ELSE 3 END,dependency_code=CASE WHEN force_id=$2 THEN 'result:won' ELSE 'result:lost' END WHERE slot_key=$1 AND task_type=9 AND status=0",c,t);finish.Parameters.AddWithValue(group.slot);finish.Parameters.AddWithValue(owner);await finish.ExecuteNonQueryAsync(ct);}}}return changed;}

    async Task<bool> SpawnYellowPhaseAsync(NpgsqlConnection c,NpgsqlTransaction t,long task,int level,int phase,CancellationToken ct)
    {var changed=false;foreach(var row in content.NationYellowTurbanNpcs.Where(x=>x.KingdomLevel==level&&x.Type==phase)){foreach(var city in Ids(row.CityIds)){await using(var occupy=new NpgsqlCommand("UPDATE world_cities SET owner_force_id=104,state=0,updated_at=now() WHERE city_id=$1 AND NOT EXISTS(SELECT 1 FROM nation_event_npcs WHERE scheduled_task_id=$2 AND spawn_key LIKE $3)",c,t)){occupy.Parameters.AddWithValue(city);occupy.Parameters.AddWithValue(task);occupy.Parameters.AddWithValue($"phase:{phase}:city:{city}:%");await occupy.ExecuteNonQueryAsync(ct);}for(var i=0;i<row.Num;i++)changed|=await InsertAsync(c,t,task,0,9,city,row.ArmyId,$"phase:{phase}:city:{city}:row:{row.Id}:npc:{i}",ct);}}return changed;}
    static async Task<bool> PhaseClearedAsync(NpgsqlConnection c,NpgsqlTransaction t,long task,int phase,CancellationToken ct){await using var cmd=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM nation_event_npcs WHERE scheduled_task_id=$1 AND spawn_key LIKE $2) AND NOT EXISTS(SELECT 1 FROM nation_event_npcs WHERE scheduled_task_id=$1 AND spawn_key LIKE $2 AND defeated=false)",c,t);cmd.Parameters.AddWithValue(task);cmd.Parameters.AddWithValue($"phase:{phase}:%");return Convert.ToBoolean(await cmd.ExecuteScalarAsync(ct));}

    async Task AdvanceNationRoundsAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken ct)
    {var expansions=new List<(string slot,int force,int serial,int status,int balance,DateTimeOffset start,DateTimeOffset end)>();await using(var q=new NpgsqlCommand("SELECT s.slot_key,s.force_id,s.event_serial,s.status,s.balance_before,s.starts_at,s.ends_at FROM nation_scheduled_tasks s WHERE s.task_type=6 AND s.status IN(1,3) AND s.event_serial BETWEEN 1 AND 2 AND NOT EXISTS(SELECT 1 FROM nation_scheduled_tasks n WHERE n.slot_key=s.slot_key AND n.force_id=s.force_id AND n.task_type=6 AND n.event_serial=s.event_serial+1) FOR UPDATE",c,t)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))expansions.Add((r.GetString(0),r.GetInt16(1),r.GetInt16(2),r.GetInt16(3),r.GetInt16(4),r.GetFieldValue<DateTimeOffset>(5),r.GetFieldValue<DateTimeOffset>(6)));}foreach(var x in expansions){var balance=Math.Max(-1,x.balance+(x.status==1?1:-1));long owned;await using(var q=new NpgsqlCommand("SELECT count(*) FROM world_cities WHERE owner_force_id=$1",c,t)){q.Parameters.AddWithValue(x.force);owned=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}var target=content.NationExpansionTargets.FirstOrDefault(v=>v.Win==balance)??content.NationExpansionTargets.OrderBy(v=>Math.Abs(v.Win-balance)).First();var serial=x.serial+1;await using var add=new NpgsqlCommand("INSERT INTO nation_scheduled_tasks(slot_key,force_id,task_type,task_id,target,starts_at,ends_at,status,dependency_code,event_serial,balance_before) VALUES($1,$2,6,$3,$4,$5,$6,0,'',$7,$8) ON CONFLICT DO NOTHING",c,t);add.Parameters.AddWithValue(x.slot);add.Parameters.AddWithValue(x.force);add.Parameters.AddWithValue(x.force*100+6+serial*10);add.Parameters.AddWithValue(owned+target.Tc);add.Parameters.AddWithValue(x.end);add.Parameters.AddWithValue(x.end.AddMinutes(30));add.Parameters.AddWithValue(serial);add.Parameters.AddWithValue(balance);await add.ExecuteNonQueryAsync(ct);}
     var sweeps=new List<(long id,string slot,int force,int serial,DateTimeOffset end)>();await using(var q=new NpgsqlCommand("SELECT s.id,s.slot_key,s.force_id,s.event_serial,s.ends_at FROM nation_scheduled_tasks s WHERE s.task_type=7 AND s.status=0 AND s.event_serial>0 AND EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id) AND NOT EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id AND n.defeated=false) FOR UPDATE",c,t)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))sweeps.Add((r.GetInt64(0),r.GetString(1),r.GetInt16(2),r.GetInt16(3),r.GetFieldValue<DateTimeOffset>(4)));}foreach(var x in sweeps){await using(var done=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET status=1,dependency_code='result:won' WHERE id=$1 AND status=0",c,t)){done.Parameters.AddWithValue(x.id);await done.ExecuteNonQueryAsync(ct);}if(x.serial>=content.NationSweepWaves.Max(v=>v.Index))continue;var serial=x.serial+1;var next=DateTimeOffset.UtcNow.AddMinutes(1);if(next>=x.end)continue;await using var add=new NpgsqlCommand("INSERT INTO nation_scheduled_tasks(slot_key,force_id,task_type,task_id,target,starts_at,ends_at,status,dependency_code,event_serial) VALUES($1,$2,7,$3,0,$4,$5,0,'',$6) ON CONFLICT DO NOTHING",c,t);add.Parameters.AddWithValue(x.slot);add.Parameters.AddWithValue(x.force);add.Parameters.AddWithValue(x.force*100+7+serial*10);add.Parameters.AddWithValue(next);add.Parameters.AddWithValue(x.end);add.Parameters.AddWithValue(serial);await add.ExecuteNonQueryAsync(ct);}}

    static async Task ResolveNationTaskEndsAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken ct)
    {await using(var competitive=new NpgsqlCommand("WITH scores AS(SELECT slot_key,task_type,force_id,sum(progress) score,max(sum(progress)) OVER(PARTITION BY slot_key,task_type) best FROM nation_scheduled_tasks WHERE task_type=ANY($1) AND ends_at<=now() GROUP BY slot_key,task_type,force_id) UPDATE nation_scheduled_tasks s SET status=CASE WHEN x.score=x.best THEN 1 ELSE 3 END,dependency_code=CASE WHEN x.score=x.best THEN 'result:won' ELSE 'result:lost' END FROM scores x WHERE s.slot_key=x.slot_key AND s.task_type=x.task_type AND s.force_id=x.force_id AND s.status IN(0,1,2) AND s.dependency_code NOT LIKE 'result:%'",c,t)){competitive.Parameters.AddWithValue(new[]{2,3,4,5});await competitive.ExecuteNonQueryAsync(ct);}await using(var expansion=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET status=CASE WHEN progress>=target AND target>0 THEN 1 ELSE 3 END,dependency_code=CASE WHEN progress>=target AND target>0 THEN 'result:won' ELSE 'result:lost' END WHERE task_type=6 AND status IN(0,1,2) AND dependency_code NOT LIKE 'result:%' AND ends_at<=now()",c,t))await expansion.ExecuteNonQueryAsync(ct);await using(var sweep=new NpgsqlCommand("UPDATE nation_scheduled_tasks s SET status=CASE WHEN NOT EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id AND n.defeated=false) AND EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id) THEN 1 ELSE 3 END,dependency_code=CASE WHEN NOT EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id AND n.defeated=false) AND EXISTS(SELECT 1 FROM nation_event_npcs n WHERE n.scheduled_task_id=s.id) THEN 'result:won' ELSE 'result:lost' END WHERE s.task_type=7 AND s.status IN(0,1,2) AND s.dependency_code NOT LIKE 'result:%' AND s.ends_at<=now()",c,t))await sweep.ExecuteNonQueryAsync(ct);await using(var competition=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET status=3,dependency_code='result:timeout' WHERE task_type=1 AND status IN(0,1,2) AND dependency_code NOT LIKE 'result:%' AND ends_at<=now()",c,t))await competition.ExecuteNonQueryAsync(ct);}

    static async Task<bool> InsertAsync(NpgsqlConnection c,NpgsqlTransaction t,long task,int force,int type,int city,int army,string key,CancellationToken ct)
    {await using var cmd=new NpgsqlCommand("INSERT INTO nation_event_npcs(scheduled_task_id,force_id,event_type,city_id,army_id,spawn_key) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(scheduled_task_id,spawn_key) DO NOTHING",c,t);cmd.Parameters.AddWithValue(task);cmd.Parameters.AddWithValue(force);cmd.Parameters.AddWithValue(type);cmd.Parameters.AddWithValue(city);cmd.Parameters.AddWithValue(army);cmd.Parameters.AddWithValue(key);return await cmd.ExecuteNonQueryAsync(ct)==1;}
    static IEnumerable<int> Ids(string value)=>value.Split(';',StringSplitOptions.RemoveEmptyEntries).Select(int.Parse);
}





